<?php
header('Content-Type:text/html;charset=UTF-8');
$ROOT=realpath(__DIR__);$SKIP=['.git','node_modules','vendor'];$TEXT='/\.(php|js|mjs|jsx|ts|tsx|css|scss|html|htm|json|xml|svg|yml|yaml|ini|conf|md|txt)$/i';
function rp($p,$r){$x=realpath($p);return $x?ltrim(str_replace('\\','/',substr($x,strlen($r))),'/'):'';}function bp($p){global $SKIP;foreach($SKIP as $s)if(preg_match('#(^|/)'.preg_quote($s,'#').'(/|$)#',$p))return 1;return 0;}
function scan($root){global $TEXT;$fs=[];$ds=[];$it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($root,FilesystemIterator::SKIP_DOTS),RecursiveIteratorIterator::SELF_FIRST);foreach($it as $f){$p=rp($f->getPathname(),$root);if(!$p||bp($p))continue;if($f->isDir())$ds[]=$p;elseif($f->isFile())$fs[$p]=['size'=>$f->getSize(),'text'=>(bool)preg_match($TEXT,$p)];}sort($fs);sort($ds);$refs=[];$rx=[
'/\b(?:require|require_once|include|include_once)\s*\(?\s*[\'\"]([^\'\"]+)[\'\"]/i',
'/\b(?:import|export)\s+(?:[^\'\";]+?\s+from\s+)?[\'\"]([^\'\"]+)[\'\"]/i',
'/\b(?:src|href)\s*=\s*[\'\"]([^\'\"]+)[\'\"]/i',
'/url\(\s*[\'\"]?([^\'\"\)]+)[\'\"]?\s*\)/i'];
foreach($fs as $p=>$m){if(!$m['text']||$m['size']>700000)continue;$s=@file_get_contents($root.'/'.$p);if($s===false)continue;$vals=[];foreach($rx as $re){preg_match_all($re,$s,$mm);foreach($mm[1]??[] as $v){$v=trim(preg_replace('/[#?].*$/','',$v));if($v&&!preg_match('/^(https?:|data:|mailto:|javascript:|#|\/\/)/i',$v))$vals[]=$v;}}foreach(array_unique($vals) as $v){$base=dirname($p);$c=ltrim(str_replace('\\','/',($v[0]==='/'?$v:$base.'/'.$v)),'/');foreach([$c,$c.'.php',$c.'.js',$c.'.css',$c.'.json',$c.'.html',$c.'/index.php',$c.'/index.html'] as $z)if(isset($fs[$z])){$refs[]=['from'=>$p,'to'=>$z];break;}}}return ['root'=>basename($root),'files'=>array_keys($fs),'dirs'=>$ds,'refs'=>$refs,'time'=>date('H:i:s'),'ts'=>microtime(true)];}
$D=scan($ROOT);if(isset($_GET['pulse'])){header('Cache-Control:no-store');header('Content-Type:application/json');echo json_encode(['ok'=>1,'time'=>$D['time'],'ts'=>$D['ts'],'files'=>count($D['files']),'links'=>count($D['refs'])]);exit;}if(isset($_GET['data'])){header('Cache-Control:no-store');header('Content-Type:application/json');echo json_encode($D,JSON_UNESCAPED_SLASHES);exit;}
?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SmartToolz — JARVIS Live File Map</title><style>
*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#02060d;color:#eaf8ff;font-family:Inter,system-ui,Segoe UI,Arial}body:before{content:"";position:fixed;inset:0;opacity:.35;background-image:linear-gradient(#12304720 1px,transparent 1px),linear-gradient(90deg,#12304720 1px,transparent 1px);background-size:42px 42px}#cv{position:fixed;inset:0;width:100%;height:100%;cursor:grab}.drag{cursor:grabbing!important}.hud{position:fixed;z-index:4;top:16px;left:20px;right:20px;display:flex;justify-content:space-between;pointer-events:none}.brand{pointer-events:auto}.ey{font:800 8px ui-monospace;letter-spacing:2px;color:#7285a1}.ey b{color:#45f5b0;text-shadow:0 0 12px #45f5b0}.brand h1{margin:5px 0 2px;font-size:29px;letter-spacing:-1.5px}.brand h1 span{color:#24ddff;text-shadow:0 0 22px #24ddff66}.sub{font:8px ui-monospace;color:#52627e}.stats{display:flex;gap:6px}.stat,.card,.panel,.btn,.search{border:1px solid #6fa7ce24;background:#06111de8;backdrop-filter:blur(14px)}.stat{min-width:70px;padding:8px 10px;border-radius:9px}.stat small{display:block;font:700 7px ui-monospace;color:#566a86}.stat strong{font:800 12px ui-monospace}.live{color:#45f5b0}.search{position:fixed;z-index:5;top:105px;left:20px;width:235px;padding:10px;border-radius:9px;color:white;outline:0;font:800 9px ui-monospace}.panel{position:fixed;z-index:6;right:20px;top:105px;width:295px;padding:14px;border-radius:13px;display:none}.panel.show{display:block}.panel h2{font-size:14px;margin:7px 0}.k{font:800 7px ui-monospace;color:#607490;letter-spacing:1.3px}.path{font:8px ui-monospace;color:#9beeff;word-break:break-all}.meta{margin-top:8px;font:8px ui-monospace;color:#7f91ad;line-height:1.8}.close{float:right;background:none;border:0;color:#71829d;font-size:17px}.tools{position:fixed;z-index:5;left:20px;bottom:16px;display:flex;gap:6px}.btn{padding:8px 11px;border-radius:8px;color:#bdd0e7;font:800 8px ui-monospace;cursor:pointer}.btn:hover{border-color:#24ddff88;color:#fff}.status{position:fixed;z-index:5;left:20px;bottom:52px;font:700 7px ui-monospace;color:#52647f}.pulse{display:inline-block;width:6px;height:6px;border-radius:50%;background:#45f5b0;box-shadow:0 0 14px #45f5b0;margin-right:6px}.load{position:fixed;z-index:20;inset:0;display:grid;place-items:center;background:#02060df8}.loader{text-align:center}.loader i{display:block;width:52px;height:52px;margin:auto;border:2px solid #ffffff10;border-top-color:#24ddff;border-right-color:#8f70ff;border-radius:50%;animation:spin .7s linear infinite}.loader b{display:block;margin-top:12px;font-size:11px}.loader small{display:block;margin-top:5px;color:#61728e;font:8px ui-monospace}@keyframes spin{to{transform:rotate(360deg)}}@media(max-width:700px){.hud{top:10px;left:11px;right:11px}.brand h1{font-size:22px}.sub{display:none}.stat{min-width:48px;padding:6px}.stat small{font-size:6px}.stat strong{font-size:9px}.search{top:76px;left:11px;width:190px}.panel{top:76px;left:11px;right:11px;width:auto}.tools{left:11px;bottom:11px}}
</style></head><body><div class="load" id="load"><div class="loader"><i></i><b>JARVIS NEURAL CORE</b><small>Scanning live server filesystem…</small></div></div><div class="hud"><div class="brand"><div class="ey"><b>●</b> SMARTTOOLZ / LIVE SYSTEM</div><h1>Full File <span>Mind Map</span></h1><div class="sub">ACTUAL SERVER FILES • DETECTED DEPENDENCIES • LIVE HEARTBEAT</div></div><div class="stats"><div class="stat"><small>FILES</small><strong id="fc">0</strong></div><div class="stat"><small>LINKS</small><strong id="ec">0</strong></div><div class="stat"><small>PULSES</small><strong id="pc">0</strong></div><div class="stat"><small>STATE</small><strong id="state" class="live">LIVE</strong></div></div></div><input id="search" class="search" placeholder="Search file / folder…"><canvas id="cv"></canvas><div id="panel" class="panel"><button id="close" class="close">×</button><div class="k">NEURAL NODE</div><h2 id="pn"></h2><div id="pp" class="path"></div><div id="pm" class="meta"></div></div><div class="status"><span class="pulse"></span>SERVER HEARTBEAT <b id="hb">CONNECTING</b></div><div class="tools"><button class="btn" id="fit">FIT</button><button class="btn" id="pause">PAUSE</button><button class="btn" id="rescan">RESCAN</button></div>
<script>
const D=<?php echo json_encode($D,JSON_UNESCAPED_SLASHES);?>,cv=document.getElementById('cv'),g=cv.getContext('2d');let W,H,dpr=1,nodes=[],edges=[],sel=null,hov=null,zoom=1,ox=0,oy=0,drag=0,lx=0,ly=0,paused=0,pulses=0;
function size(){dpr=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;cv.width=W*dpr;cv.height=H*dpr;g.setTransform(dpr,0,0,dpr,0,0)}addEventListener('resize',size);size();
function build(){const fm=new Map;D.dirs.forEach(p=>fm.set(p,{id:'d:'+p,path:p,name:p.split('/').pop()+'/',folder:1,x:0,y:0,r:8}));nodes=D.files.map(p=>({id:'f:'+p,path:p,name:p.split('/').pop(),folder:0,x:0,y:0,r:3}));nodes=[...fm.values(),...nodes];const m=new Map(nodes.map(n=>[n.id,n]));for(const n of nodes){const a=n.path.split('/');if(a.length>1){const p=a.slice(0,-1).join('/');if(m.has('d:'+p))edges.push({a:m.get('d:'+p),b:n,t:'tree',phase:Math.random()*6})}}for(const r of D.refs){const a=m.get('f:'+r.from),b=m.get('f:'+r.to);if(a&&b)edges.push({a,b,t:'dep',phase:Math.random()*6})}layout();document.getElementById('fc').textContent=D.files.length;document.getElementById('ec').textContent=D.refs.length}
function layout(){const cx=W/2,cy=H/2,roots=nodes.filter(n=>n.folder&&!n.path.includes('/'));roots.forEach((r,i)=>{const a=i/Math.max(1,roots.length)*Math.PI*2-Math.PI/2,rr=Math.min(W,H)*.27;r.x=cx+Math.cos(a)*rr;r.y=cy+Math.sin(a)*rr;const kids=nodes.filter(n=>!n.folder&&n.path.split('/')[0]===r.path),span=Math.min(1.8,Math.max(.7,kids.length*.035)),rad=Math.min(W,H)*(.09+Math.min(.17,kids.length*.001));kids.forEach((n,j)=>{const aa=a-span/2+(j/Math.max(1,kids.length-1))*span;n.x=r.x+Math.cos(aa)*rad;n.y=r.y+Math.sin(aa)*rad})});const loose=nodes.filter(n=>!n.folder&&!roots.some(r=>n.path.split('/')[0]===r.path));loose.forEach((n,i)=>{const a=i/Math.max(1,loose.length)*Math.PI*2;n.x=cx+Math.cos(a)*Math.min(W,H)*.39;n.y=cy+Math.sin(a)*Math.min(W,H)*.39})}
function P(n){return{x:n.x*zoom+ox,y:n.y*zoom+oy}}function hit(mx,my){let b=null,bd=18;for(const n of nodes){const p=P(n),d=Math.hypot(mx-p.x,my-p.y);if(d<bd){bd=d;b=n}}return b}function near(n){return sel&&edges.some(e=>(e.a===n&&e.b===sel)||(e.b===n&&e.a===sel))}
function draw(t){g.clearRect(0,0,W,H);for(const e of edges){const a=P(e.a),b=P(e.b),hot=e.a===sel||e.b===sel||e.a===hov||e.b===hov;g.beginPath();g.moveTo(a.x,a.y);g.lineTo(b.x,b.y);g.strokeStyle=hot?'rgba(36,221,255,.8)':e.t==='dep'?'rgba(36,221,255,.2)':'rgba(143,112,255,.08)';g.lineWidth=hot?2:e.t==='dep'?1:.55;g.stroke();if(e.t==='dep'&&!paused){const q=(t/1800+e.phase)%1,px=a.x+(b.x-a.x)*q,py=a.y+(b.y-a.y)*q;g.beginPath();g.arc(px,py,2.5+Math.sin(t/100+e.phase)*.5,0,7);g.fillStyle='#45f5b0';g.shadowBlur=16;g.shadowColor='#45f5b0';g.fill();g.shadowBlur=0}}for(const n of nodes){const p=P(n),hot=n===sel||n===hov||near(n),r=(n.r+(hot?2:0))*Math.max(.7,Math.min(1.8,zoom));g.beginPath();g.arc(p.x,p.y,r,0,7);g.fillStyle=n.folder?'#8f70ff':hot?'#65f5ff':'#10243a';g.shadowBlur=hot?18:4;g.shadowColor=n.folder?'#8f70ff':'#24ddff';g.fill();g.shadowBlur=0;if(zoom>.75||hot){g.fillStyle=hot?'#eafcff':'#667997';g.font=(hot?'9':'7')+'px ui-monospace';g.fillText(n.name,p.x+r+4,p.y+3)}}document.getElementById('pc').textContent=pulses;requestAnimationFrame(draw)}
cv.onpointerdown=e=>{drag=1;lx=e.clientX;ly=e.clientY;cv.classList.add('drag')};addEventListener('pointermove',e=>{if(drag){ox+=e.clientX-lx;oy+=e.clientY-ly;lx=e.clientX;ly=e.clientY}hov=hit(e.clientX,e.clientY)});addEventListener('pointerup',e=>{drag=0;cv.classList.remove('drag');const n=hit(e.clientX,e.clientY);if(n){sel=n;document.getElementById('panel').classList.add('show');document.getElementById('pn').textContent=n.name;document.getElementById('pp').textContent=n.path;document.getElementById('pm').textContent=(n.folder?'FOLDER':'FILE')+' • '+edges.filter(e=>e.a===n||e.b===n).length+' local links'}});cv.onwheel=e=>{e.preventDefault();zoom=Math.max(.25,Math.min(4,zoom*Math.exp(-e.deltaY*.001)))};
document.getElementById('close').onclick=()=>document.getElementById('panel').classList.remove('show');document.getElementById('pause').onclick=e=>{paused=!paused;e.target.textContent=paused?'PLAY':'PAUSE';document.getElementById('state').textContent=paused?'PAUSED':'LIVE'};document.getElementById('fit').onclick=()=>{zoom=1;ox=0;oy=0;layout()};document.getElementById('rescan').onclick=()=>location.reload();document.getElementById('search').oninput=e=>{const q=e.target.value.toLowerCase().trim();if(!q){sel=null;return}const n=nodes.find(n=>n.path.toLowerCase().includes(q));if(n){sel=n;ox=W/2-n.x*zoom;oy=H/2-n.y*zoom;document.getElementById('panel').classList.add('show');document.getElementById('pn').textContent=n.name;document.getElementById('pp').textContent=n.path}};addEventListener('keydown',e=>{if(e.key.toLowerCase()==='r'){zoom=1;ox=0;oy=0;layout()}});
async function heartbeat(){try{const r=await fetch(location.pathname+'?pulse=1&_='+Date.now(),{cache:'no-store'}),d=await r.json();if(d.ok){pulses++;document.getElementById('hb').textContent=d.time;document.getElementById('state').textContent='LIVE'}}catch(e){document.getElementById('hb').textContent='OFFLINE';document.getElementById('state').textContent='OFFLINE'}setTimeout(heartbeat,2000)}
build();document.getElementById('load').style.display='none';heartbeat();requestAnimationFrame(draw);
</script></body></html>